-- Replace generic MAPEH and TLE catalog stems with applied, bilingual multiple-choice questions.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil,
    explanation_en=v.explanation_en, explanation_fil=v.explanation_fil,
    options=v.options::jsonb
FROM (VALUES
 ($$starter-mapeh-warmup$$,$$Your class is about to begin a vigorous dance routine. Which opening best prepares the body?$$,$$Magsisimula na ang klase sa masiglang sayaw. Aling panimula ang pinakamainam na paghahanda sa katawan?$$,$$A gradual warm-up raises activity gently and prepares the body for more intense movement.$$,$$Unti-unting itinataas ng warm-up ang antas ng kilos upang ihanda ang katawan sa masiglang galaw.$$,$$[{"en":"Start with light movement, then gradually increase intensity.","fil":"Magsimula sa magaang galaw at unti-unting dagdagan ang tindi.","correct":true},{"en":"Sit still until the music starts.","fil":"Umupo lamang hanggang tumugtog ang musika.","correct":false},{"en":"Begin with the hardest jumps immediately.","fil":"Agad magsimula sa pinakamahirap na pagtalon.","correct":false},{"en":"Hold one painful stretch without moving.","fil":"Manatili sa masakit na unat nang hindi gumagalaw.","correct":false}]$$),
 ($$starter-mapeh-activity$$,$$A student wants to build a healthier routine. Which plan best reflects regular physical activity?$$,$$Nais magkaroon ng mas malusog na gawain ang isang mag-aaral. Aling plano ang nagpapakita ng regular na pisikal na aktibidad?$$,$$Regular activity means moving on a consistent basis, choosing age-appropriate activities across the week.$$,$$Nangangahulugan ang regular na aktibidad ng tuloy-tuloy na pagkilos sa buong linggo gamit ang angkop na gawain.$$,$$[{"en":"Schedule enjoyable movement on most days of the week.","fil":"Magplano ng kasiya-siyang pagkilos sa karamihan ng mga araw sa isang linggo.","correct":true},{"en":"Exercise once a month only.","fil":"Mag-ehersisyo lamang isang beses bawat buwan.","correct":false},{"en":"Avoid movement whenever possible.","fil":"Iwasan ang pagkilos hangga’t maaari.","correct":false},{"en":"Do one exhausting workout and never repeat it.","fil":"Gumawa ng nakapapagod na ehersisyo nang minsanan lamang.","correct":false}]$$),
 ($$starter-mapeh-sleep$$,$$A teenager has school early tomorrow. Which bedtime plan supports the usual sleep recommendation?$$,$$Maagang papasok bukas ang isang teenager. Aling oras ng pagtulog ang tumutugon sa karaniwang rekomendasyon?$$,$$Teenagers generally need about 8 to 10 hours of sleep in each 24-hour period.$$,$$Karaniwang nangangailangan ang mga teenager ng humigit-kumulang 8 hanggang 10 oras na tulog sa bawat 24 oras.$$,$$[{"en":"Allow about 8–10 hours for sleep.","fil":"Maglaan ng humigit-kumulang 8–10 oras para matulog.","correct":true},{"en":"Plan for 3 hours.","fil":"Magplano ng 3 oras lamang.","correct":false},{"en":"Stay awake all night to study.","fil":"Magpuyat buong gabi para mag-aral.","correct":false},{"en":"Sleep only when the weekend begins.","fil":"Sa katapusan lamang ng linggo matulog.","correct":false}]$$),
 ($$starter-mapeh-handwash$$,$$After playing outside, a learner is about to eat. Which handwashing routine is most effective?$$,$$Pagkatapos maglaro sa labas, kakain na ang mag-aaral. Aling paraan ng paghuhugas ng kamay ang pinakamabisa?$$,$$Soap, water, and at least 20 seconds of scrubbing help remove dirt and germs.$$,$$Nakatutulong mag-alis ng dumi at mikrobyo ang sabon, tubig, at pagkuskos nang hindi bababa sa 20 segundo.$$,$$[{"en":"Scrub with soap and water for at least 20 seconds.","fil":"Kuskusin gamit ang sabon at tubig nang hindi bababa sa 20 segundo.","correct":true},{"en":"Rinse fingertips for one second.","fil":"Banlawan ang mga dulo ng daliri nang isang segundo.","correct":false},{"en":"Wipe hands on clothing.","fil":"Punasan ang kamay sa damit.","correct":false},{"en":"Use water only after touching a dirty surface.","fil":"Tubig lamang ang gamitin matapos humawak sa maruming bagay.","correct":false}]$$),
 ($$starter-mapeh-water$$,$$During a long practice, an athlete sweats heavily. What is a sensible way to replace lost fluid?$$,$$Pinagpapawisan nang husto ang atleta sa mahabang ensayo. Ano ang makatuwirang paraan upang mapalitan ang nawawalang likido?$$,$$Drinking water helps replace fluid lost through sweat during activity.$$,$$Nakatutulong ang pag-inom ng tubig na palitan ang likidong nawawala sa pagpapawis habang aktibo.$$,$$[{"en":"Drink water regularly during and after activity.","fil":"Uminom ng tubig nang regular habang at pagkatapos ng aktibidad.","correct":true},{"en":"Avoid all fluids until practice ends.","fil":"Iwasan ang lahat ng inumin hanggang matapos ang ensayo.","correct":false},{"en":"Replace water with candy.","fil":"Palitan ng kendi ang tubig.","correct":false},{"en":"Drink only if feeling faint.","fil":"Uminom lamang kapag nahihilo na.","correct":false}]$$),
 ($$starter-mapeh-tempo$$,$$A band plays the same melody first slowly, then quickly. Which musical element changed?$$,$$Tinugtog ng banda ang parehong himig nang mabagal at pagkatapos ay mabilis. Aling elemento ng musika ang nagbago?$$,$$Tempo is the speed at which music is performed.$$,$$Ang tempo ang bilis ng pagtugtog o pag-awit ng musika.$$,$$[{"en":"Tempo","fil":"Tempo","correct":true},{"en":"Dynamics","fil":"Dynamics o lakas ng tunog","correct":false},{"en":"Pitch","fil":"Pitch o taas-baba ng tono","correct":false},{"en":"Timbre","fil":"Timbre o kulay ng tunog","correct":false}]$$),
 ($$starter-mapeh-dynamics$$,$$A conductor asks the choir to sing a section softly, then loudly. What is being changed?$$,$$Inutusan ng konduktor ang koro na umawit nang mahina at pagkatapos ay malakas. Ano ang binabago?$$,$$Dynamics indicate how loud or soft a musical passage should sound.$$,$$Ipinakikita ng dynamics kung gaano kalakas o kahina ang isang bahagi ng musika.$$,$$[{"en":"Dynamics","fil":"Dynamics","correct":true},{"en":"Tempo","fil":"Tempo","correct":false},{"en":"Rhythm","fil":"Rhythm","correct":false},{"en":"Melody direction only","fil":"Direksiyon lamang ng himig","correct":false}]$$),
 ($$starter-mapeh-rhythm$$,$$A drummer repeats a pattern of beats and pauses that the dancers follow. Which element organizes that pattern?$$,$$Inuulit ng drummer ang padron ng kumpas at paghinto na sinusundan ng mga mananayaw. Aling elemento ang nag-aayos sa padron?$$,$$Rhythm organizes sounds and silences over time.$$,$$Inaayos ng rhythm ang mga tunog at katahimikan sa paglipas ng panahon.$$,$$[{"en":"Rhythm","fil":"Rhythm","correct":true},{"en":"Color","fil":"Kulay","correct":false},{"en":"Volume alone","fil":"Lakas ng tunog lamang","correct":false},{"en":"Stage position","fil":"Posisyon sa entablado","correct":false}]$$),
 ($$starter-mapeh-primary-colors$$,$$In a traditional painting activity, which set is commonly taught as the primary pigment colors?$$,$$Sa tradisyonal na gawain sa pagpipinta, aling pangkat ang karaniwang itinuturo bilang pangunahing kulay ng pigment?$$,$$Traditional painting lessons commonly use red, yellow, and blue as primary pigment colors.$$,$$Karaniwang itinuturo sa tradisyonal na pagpipinta ang pula, dilaw, at asul bilang pangunahing kulay ng pigment.$$,$$[{"en":"Red, yellow, and blue","fil":"Pula, dilaw, at asul","correct":true},{"en":"Green, orange, and violet","fil":"Berde, kahel, at lila","correct":false},{"en":"Black, white, and gray","fil":"Itim, puti, at abo","correct":false},{"en":"Pink, brown, and teal","fil":"Rosas, kayumanggi, at teal","correct":false}]$$),
 ($$starter-mapeh-warm-colors$$,$$An artist wants a palette that feels sunny and energetic. Which group is usually considered warm?$$,$$Nais ng pintor ng paletang tila maaraw at masigla. Aling pangkat ang karaniwang itinuturing na warm colors?$$,$$Red, orange, and yellow are commonly described as warm colors.$$,$$Karaniwang inilalarawan ang pula, kahel, at dilaw bilang warm colors.$$,$$[{"en":"Red, orange, and yellow","fil":"Pula, kahel, at dilaw","correct":true},{"en":"Blue, green, and violet","fil":"Asul, berde, at lila","correct":false},{"en":"Blue, cyan, and teal","fil":"Asul, cyan, at teal","correct":false},{"en":"Black, gray, and white","fil":"Itim, abo, at puti","correct":false}]$$),
 ($$starter-mapeh-complementary$$,$$A designer wants strong contrast using opposite positions on a color wheel. Which pair should they choose?$$,$$Nais ng designer ng matinding contrast gamit ang magkatapat na posisyon sa color wheel. Aling pares ang dapat piliin?$$,$$Complementary colors are positioned opposite one another on a color wheel.$$,$$Magkatapat ang complementary colors sa color wheel.$$,$$[{"en":"A pair opposite each other on the color wheel","fil":"Pares na magkatapat sa color wheel","correct":true},{"en":"Two neighboring colors","fil":"Dalawang magkatabing kulay","correct":false},{"en":"Two shades of the same color","fil":"Dalawang shade ng iisang kulay","correct":false},{"en":"Only black and white","fil":"Itim at puti lamang","correct":false}]$$),
 ($$starter-mapeh-hearing$$,$$A learner listens to music with headphones for a long time. Which habit helps protect hearing?$$,$$Matagal nakikinig ng musika sa headphones ang mag-aaral. Aling gawi ang makatutulong na protektahan ang pandinig?$$,$$Keeping the volume lower and limiting listening time can reduce risk to hearing.$$,$$Nakababawas ng panganib sa pandinig ang pagpapahina ng volume at paglilimita sa oras ng pakikinig.$$,$$[{"en":"Lower the volume and take listening breaks.","fil":"Hinaan ang volume at magpahinga sa pakikinig.","correct":true},{"en":"Turn the volume to maximum.","fil":"Lakasan nang husto ang volume.","correct":false},{"en":"Keep listening even when ears hurt.","fil":"Magpatuloy kahit sumasakit ang tainga.","correct":false},{"en":"Use headphones continuously all day.","fil":"Gumamit ng headphones buong araw nang tuloy-tuloy.","correct":false}]$$),
 ($$starter-mapeh-sportsmanship$$,$$An official makes a call your team dislikes. What response shows sportsmanship?$$,$$Nagbigay ng desisyong hindi nagustuhan ng koponan ang opisyal. Aling tugon ang nagpapakita ng sportsmanship?$$,$$Sportsmanship includes respecting rules, opponents, teammates, and officials.$$,$$Kabilang sa sportsmanship ang paggalang sa mga tuntunin, kalaban, kakampi, at opisyal.$$,$$[{"en":"Respect the decision and continue playing fairly.","fil":"Igalang ang pasya at magpatuloy sa patas na paglalaro.","correct":true},{"en":"Insult the official until the call changes.","fil":"Insultuhin ang opisyal hanggang baguhin ang tawag.","correct":false},{"en":"Break the rules to get even.","fil":"Lumabag sa tuntunin bilang ganti.","correct":false},{"en":"Refuse to acknowledge the other team.","fil":"Tumangging kilalanin ang kabilang koponan.","correct":false}]$$),
 ($$starter-mapeh-balance$$,$$A gymnast holds a pose on one foot without wobbling. Which skill is being demonstrated?$$,$$Nanatili sa isang paa ang gymnast nang hindi umuuga. Anong kasanayan ang ipinakikita?$$,$$Balance is control of the body’s position while still or moving.$$,$$Ang balance ay pagkontrol sa posisyon ng katawan habang nakatigil o gumagalaw.$$,$$[{"en":"Balance","fil":"Balanse","correct":true},{"en":"Tempo","fil":"Tempo","correct":false},{"en":"Flexibility","fil":"Flexibility o kakayahang umunat","correct":false},{"en":"Endurance only","fil":"Tibay lamang","correct":false}]$$),
 ($$starter-mapeh-flexibility$$,$$A dancer moves a joint comfortably through a wide range of motion. Which fitness component is involved?$$,$$Komportableng naigagalaw ng mananayaw ang kasukasuan sa malawak na saklaw. Aling bahagi ng fitness ang sangkot?$$,$$Flexibility describes how far a joint can move comfortably through its range of motion.$$,$$Inilalarawan ng flexibility kung gaano kalawak at komportable ang galaw ng kasukasuan.$$,$$[{"en":"Flexibility","fil":"Flexibility o kakayahang umunat","correct":true},{"en":"Balance","fil":"Balanse","correct":false},{"en":"Reaction time","fil":"Bilis ng pagtugon","correct":false},{"en":"Musical tempo","fil":"Tempo ng musika","correct":false}]$$),
 ($$starter-tle-food-thermometer$$,$$A chicken dish looks browned outside, but the cook is unsure it is done inside. What should they use?$$,$$Mukhang browned na ang manok sa labas ngunit hindi tiyak ang nagluluto kung luto na ito sa loob. Ano ang dapat gamitin?$$,$$A food thermometer checks the internal temperature to determine whether food has reached a safe temperature.$$,$$Sinusukat ng food thermometer ang init sa loob ng pagkain upang malaman kung ligtas na ang temperatura nito.$$,$$[{"en":"A food thermometer","fil":"Food thermometer","correct":true},{"en":"A timer alone","fil":"Timer lamang","correct":false},{"en":"The food’s color only","fil":"Kulay lamang ng pagkain","correct":false},{"en":"A kitchen scale","fil":"Timbangan sa kusina","correct":false}]$$),
 ($$starter-tle-refrigeration$$,$$A family will cook meat tomorrow. Which storage choice slows the growth of many harmful bacteria?$$,$$Magluluto bukas ng karne ang pamilya. Aling paraan ng pag-iimbak ang nagpapabagal sa paglaki ng maraming mapaminsalang bakterya?$$,$$Refrigeration keeps perishable food cold, slowing the growth of many harmful bacteria.$$,$$Pinananatiling malamig ng refrigeration ang madaling masirang pagkain at pinababagal ang paglaki ng maraming mapaminsalang bakterya.$$,$$[{"en":"Store the meat in a refrigerator.","fil":"Itago ang karne sa refrigerator.","correct":true},{"en":"Leave it on the counter overnight.","fil":"Iwan ito sa mesa magdamag.","correct":false},{"en":"Keep it beside a warm oven.","fil":"Ilagay sa tabi ng mainit na oven.","correct":false},{"en":"Rinse it and leave it uncovered outdoors.","fil":"Banlawan at iwan itong walang takip sa labas.","correct":false}]$$),
 ($$starter-tle-separate-raw$$,$$A cook prepares raw chicken and salad. Which setup best prevents cross-contamination?$$,$$Naghahanda ang kusinero ng hilaw na manok at salad. Aling paghahanda ang pinakamainam upang maiwasan ang cross-contamination?$$,$$Raw meat should be kept separate from ready-to-eat foods, with separate clean tools and surfaces.$$,$$Dapat ihiwalay ang hilaw na karne sa pagkaing handa nang kainin at gumamit ng magkakahiwalay at malilinis na kagamitan.$$,$$[{"en":"Use separate boards and keep raw chicken away from the salad.","fil":"Gumamit ng magkahiwalay na sangkalan at ilayo ang hilaw na manok sa salad.","correct":true},{"en":"Cut both on the same unwashed board.","fil":"Hiwain ang dalawa sa iisang sangkalan na hindi hinugasan.","correct":false},{"en":"Place raw chicken on top of the salad.","fil":"Ipatong ang hilaw na manok sa salad.","correct":false},{"en":"Use the same knife without cleaning it.","fil":"Gamitin ang parehong kutsilyo nang hindi nililinis.","correct":false}]$$),
 ($$starter-tle-clean-surfaces$$,$$After handling raw ingredients, what should a cook do before preparing another food?$$,$$Pagkatapos humawak ng hilaw na sangkap, ano ang dapat gawin bago maghanda ng ibang pagkain?$$,$$Cleaning food-preparation surfaces helps reduce the spread of germs.$$,$$Nakatutulong ang paglilinis ng mga ibabaw sa paghahanda ng pagkain upang mabawasan ang pagkalat ng mikrobyo.$$,$$[{"en":"Wash and sanitize the preparation surface.","fil":"Hugasan at i-sanitize ang ibabaw na pinaghandaan.","correct":true},{"en":"Wipe it with a dry hand.","fil":"Punasan ito gamit ang tuyong kamay.","correct":false},{"en":"Cover the mess with a clean plate.","fil":"Takpan ng malinis na plato ang dumi.","correct":false},{"en":"Use the surface without cleaning.","fil":"Gamitin ang ibabaw nang hindi nililinis.","correct":false}]$$),
 ($$starter-tle-handwashing$$,$$You are about to prepare sandwiches after arriving home. What should you do first?$$,$$Maghahanda ka ng sandwich pag-uwi. Ano ang dapat gawin muna?$$,$$Wash hands with soap and water before preparing food to reduce contamination.$$,$$Maghugas ng kamay gamit ang sabon at tubig bago maghanda ng pagkain upang mabawasan ang kontaminasyon.$$,$$[{"en":"Wash your hands with soap and water.","fil":"Hugasan ang kamay gamit ang sabon at tubig.","correct":true},{"en":"Taste the ingredients first.","fil":"Tikman muna ang mga sangkap.","correct":false},{"en":"Wipe hands on an apron.","fil":"Punasan ang kamay sa apron.","correct":false},{"en":"Rinse only the fingertips briefly.","fil":"Mabilis na banlawan ang mga dulo ng daliri lamang.","correct":false}]$$),
 ($$starter-tle-passwords$$,$$A student reuses one short password for school, email, and games. Which change improves account security?$$,$$Iisang maikling password ang ginagamit ng mag-aaral sa paaralan, email, at laro. Aling pagbabago ang magpapahusay sa seguridad?$$,$$Long, unique passwords limit the damage if one account password is exposed.$$,$$Nililimitahan ng mahahaba at magkakaibang password ang pinsala kapag nalantad ang password ng isang account.$$,$$[{"en":"Create a long, unique password for each account.","fil":"Gumawa ng mahaba at natatanging password para sa bawat account.","correct":true},{"en":"Use the same easy password everywhere.","fil":"Gamitin ang iisang madaling password sa lahat.","correct":false},{"en":"Write the password in a public profile.","fil":"Ilagay ang password sa pampublikong profile.","correct":false},{"en":"Use your name as every password.","fil":"Gamitin ang pangalan bilang lahat ng password.","correct":false}]$$),
 ($$starter-tle-mfa$$,$$A service asks for a password and then a one-time code sent to your device. What security feature is this?$$,$$Humihingi ang serbisyo ng password at pagkatapos ay one-time code na ipinadala sa device mo. Anong security feature ito?$$,$$Multi-factor authentication adds another verification step beyond a password.$$,$$Nagdaragdag ang multi-factor authentication ng panibagong hakbang sa pag-verify bukod sa password.$$,$$[{"en":"Multi-factor authentication","fil":"Multi-factor authentication","correct":true},{"en":"A password hint","fil":"Pahiwatig ng password","correct":false},{"en":"A public username","fil":"Pampublikong username","correct":false},{"en":"Automatic file backup","fil":"Awtomatikong backup ng file","correct":false}]$$),
 ($$starter-tle-phishing$$,$$An email claims your account will close today and asks you to sign in through an unfamiliar link. What is the safest response?$$,$$Sinasabi ng email na isasara ngayon ang account mo at pinapapindot ka sa hindi pamilyar na link. Ano ang pinakaligtas na tugon?$$,$$Phishing messages create urgency to trick people into sharing information or opening unsafe links.$$,$$Gumagamit ng pagmamadali ang phishing upang malinlang ang tao na magbahagi ng impormasyon o magbukas ng mapanganib na link.$$,$$[{"en":"Do not click; verify through the service’s official website.","fil":"Huwag pindutin; mag-verify sa opisyal na website ng serbisyo.","correct":true},{"en":"Reply with your password.","fil":"Sumagot gamit ang password.","correct":false},{"en":"Open the link and enter all requested details.","fil":"Buksan ang link at ilagay ang lahat ng hinihinging detalye.","correct":false},{"en":"Forward it to friends so they can try it.","fil":"Ipasa sa mga kaibigan upang subukan nila.","correct":false}]$$),
 ($$starter-tle-backups$$,$$A learner’s laptop stops working before a project deadline. Which habit would make recovery easier?$$,$$Tumigil sa paggana ang laptop ng mag-aaral bago ang deadline ng proyekto. Aling gawi ang magpapadali sa pagbawi ng file?$$,$$A separate backup can restore files if a device is lost or damaged.$$,$$Maaaring maibalik ng hiwalay na backup ang mga file kapag nawala o nasira ang device.$$,$$[{"en":"Keep a recent copy in a separate backup location.","fil":"Magtabi ng bagong kopya sa hiwalay na lokasyon bilang backup.","correct":true},{"en":"Save the only copy on the laptop.","fil":"Itago ang nag-iisang kopya sa laptop.","correct":false},{"en":"Delete older versions immediately.","fil":"Agad burahin ang mga lumang bersyon.","correct":false},{"en":"Share the password instead of copying files.","fil":"Ibahagi ang password sa halip na kopyahin ang mga file.","correct":false}]$$),
 ($$starter-tle-updates$$,$$A phone offers an operating-system update that includes security fixes. What is a good practice?$$,$$Nag-aalok ang telepono ng update ng operating system na may security fixes. Ano ang mabuting gawain?$$,$$Updates often include fixes for known security problems; install them from trusted sources.$$,$$Madalas may ayos para sa kilalang problema sa seguridad ang mga update; mag-install mula sa pinagkakatiwalaang pinagmulan.$$,$$[{"en":"Install the update from the device’s official settings.","fil":"I-install ang update mula sa opisyal na settings ng device.","correct":true},{"en":"Ignore every update permanently.","fil":"Balewalain habambuhay ang lahat ng update.","correct":false},{"en":"Download an update from an unknown pop-up.","fil":"Mag-download mula sa hindi kilalang pop-up.","correct":false},{"en":"Disable security features to make updates faster.","fil":"I-disable ang security features para bumilis ang update.","correct":false}]$$),
 ($$starter-tle-privacy$$,$$An unknown website asks for your home address and school password to view a game. What should you do?$$,$$Humihingi ang hindi kilalang website ng address ng bahay at password sa paaralan upang makita ang laro. Ano ang dapat gawin?$$,$$Sensitive personal information should not be shared with unknown websites or senders.$$,$$Hindi dapat ibahagi sa hindi kilalang website o nagpadala ang sensitibong personal na impormasyon.$$,$$[{"en":"Do not provide the details; check with a trusted adult.","fil":"Huwag ibigay ang detalye; kumonsulta sa pinagkakatiwalaang nakatatanda.","correct":true},{"en":"Enter everything to unlock the game.","fil":"Ilagay ang lahat upang mabuksan ang laro.","correct":false},{"en":"Post the details in a public comment.","fil":"I-post ang detalye sa pampublikong komento.","correct":false},{"en":"Send the password to the site owner by email.","fil":"I-email ang password sa may-ari ng site.","correct":false}]$$),
 ($$starter-tle-urls$$,$$A message includes a link to a prize page with a misspelled company name. What should you check before opening it?$$,$$May link ang mensahe sa pahina ng premyo na mali ang baybay ng pangalan ng kumpanya. Ano ang dapat suriin bago ito buksan?$$,$$Checking the actual web address can reveal suspicious or impersonating sites.$$,$$Maaaring makita sa pagsusuri ng aktuwal na web address ang kahina-hinala o nagpapanggap na site.$$,$$[{"en":"Inspect the full URL and verify it through an official source.","fil":"Suriin ang buong URL at beripikahin ito sa opisyal na pinagmulan.","correct":true},{"en":"Trust it because the message has a logo.","fil":"Pagkatiwalaan dahil may logo ang mensahe.","correct":false},{"en":"Open it first and decide later.","fil":"Buksan muna at magpasya pagkatapos.","correct":false},{"en":"Share it publicly to ask strangers.","fil":"Ibahagi sa publiko at magtanong sa hindi kakilala.","correct":false}]$$),
 ($$starter-tle-public-wifi$$,$$You are connected to café Wi-Fi and need to enter sensitive information. What should you do?$$,$$Nakakonekta ka sa Wi-Fi ng café at kailangan mong maglagay ng sensitibong impormasyon. Ano ang dapat gawin?$$,$$On public Wi-Fi, avoid entering sensitive information on sites without HTTPS; use trusted secure connections.$$,$$Sa pampublikong Wi-Fi, iwasang maglagay ng sensitibong impormasyon sa site na walang HTTPS; gumamit ng ligtas at pinagkakatiwalaang koneksyon.$$,$$[{"en":"Check for HTTPS and use a trusted secure connection.","fil":"Tiyaking HTTPS ang site at gumamit ng ligtas na koneksyon.","correct":true},{"en":"Ignore browser security warnings.","fil":"Balewalain ang babala ng browser.","correct":false},{"en":"Send the information in an open chat.","fil":"Ipadala ang impormasyon sa pampublikong chat.","correct":false},{"en":"Turn off the device’s screen lock.","fil":"I-off ang screen lock ng device.","correct":false}]$$),
 ($$starter-tle-screen-lock$$,$$A learner leaves a tablet on a library table to get a book. Which setting helps protect it?$$,$$Iniwan ng mag-aaral ang tablet sa mesa ng aklatan upang kumuha ng libro. Aling setting ang makatutulong magprotekta rito?$$,$$A screen lock helps prevent casual access when a device is unattended.$$,$$Nakakahadlang ang screen lock sa madaling pag-access kapag walang nagbabantay sa device.$$,$$[{"en":"Set a strong screen lock.","fil":"Magtakda ng matibay na screen lock.","correct":true},{"en":"Keep the device unlocked.","fil":"Iwang bukas ang device.","correct":false},{"en":"Display the password beside it.","fil":"Ipakita ang password sa tabi nito.","correct":false},{"en":"Turn off all security settings.","fil":"I-off ang lahat ng security setting.","correct":false}]$$),
 ($$starter-tle-report-phishing$$,$$Several coworkers receive the same suspicious password-reset email. What action helps protect the group?$$,$$Nakatanggap ang ilang katrabaho ng parehong kahina-hinalang email para mag-reset ng password. Anong hakbang ang makatutulong sa grupo?$$,$$Reporting suspicious messages lets an organization warn others and respond to the threat.$$,$$Natutulungan ng pag-uulat sa kahina-hinalang mensahe ang organisasyon na magbabala sa iba at tumugon sa banta.$$,$$[{"en":"Report it through the organization’s approved channel.","fil":"Iulat ito sa aprubadong paraan ng organisasyon.","correct":true},{"en":"Forward it to everyone with the link intact.","fil":"Ipasa sa lahat kasama ang link.","correct":false},{"en":"Reply with account information.","fil":"Sumagot gamit ang impormasyon ng account.","correct":false},{"en":"Delete it silently without warning anyone.","fil":"Burahin nang walang babala sa iba.","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
